import{_ as e,o as t,c as s,ag as n}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Load Balancing — L4 vs L7, DNS Routing, Redundancy","description":"","frontmatter":{},"headers":[],"relativePath":"system_design/load_balancing/LoadBalancing.md","filePath":"system_design/load_balancing/LoadBalancing.md"}'),o={name:"system_design/load_balancing/LoadBalancing.md"};function i(r,a,l,d,c,h){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="load-balancing-—-l4-vs-l7-dns-routing-redundancy" tabindex="-1">Load Balancing — L4 vs L7, DNS Routing, Redundancy <a class="header-anchor" href="#load-balancing-—-l4-vs-l7-dns-routing-redundancy" aria-label="Permalink to &quot;Load Balancing — L4 vs L7, DNS Routing, Redundancy&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="why-load-balancing-exists" tabindex="-1">Why load balancing exists <a class="header-anchor" href="#why-load-balancing-exists" aria-label="Permalink to &quot;Why load balancing exists&quot;">​</a></h3><p>A load balancer sits in front of multiple servers and distributes incoming traffic across them. Goals:</p><ul><li><strong>Scalability</strong> — handle more traffic by adding servers</li><li><strong>Availability</strong> — traffic continues if a server fails</li><li><strong>Fault tolerance</strong> — no single machine becomes a bottleneck</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Users → Load Balancer → [Server A | Server B | Server C]</span></span></code></pre></div><p>The load balancer decides which backend server receives each request.</p><h3 id="layer-4-vs-layer-7-—-the-key-distinction" tabindex="-1">Layer 4 vs Layer 7 — the key distinction <a class="header-anchor" href="#layer-4-vs-layer-7-—-the-key-distinction" aria-label="Permalink to &quot;Layer 4 vs Layer 7 — the key distinction&quot;">​</a></h3><p><strong>Layer 4 (transport layer)</strong> routes using source/destination IP, ports, and TCP/UDP metadata. It does NOT inspect HTTP request contents — it only sees <code>IP + port</code> and forwards the connection. Think: <em>&quot;Who is talking to me?&quot;</em></p><p><strong>Layer 7 (application layer)</strong> can inspect URL paths, HTTP headers, cookies, and hostnames. Think: <em>&quot;What are they asking for?&quot;</em></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/*    → API servers</span></span>
<span class="line"><span>/admin/*  → Admin servers</span></span></code></pre></div><p>Layer 7 is application-aware.</p><h3 id="combining-l4-and-l7" tabindex="-1">Combining L4 and L7 <a class="header-anchor" href="#combining-l4-and-l7" aria-label="Permalink to &quot;Combining L4 and L7&quot;">​</a></h3><p>One layer makes broad routing decisions; another makes application-specific ones:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User → Global routing (L4-style) → Singapore region → NGINX / ALB (L7) → microservices</span></span></code></pre></div><p>Example: a user from Malaysia is routed to the Singapore region, then L7 routing splits <code>/products</code>, <code>/admin</code>, <code>/api</code> to the correct backend services.</p><h3 id="dns-based-load-balancing" tabindex="-1">DNS-based load balancing <a class="header-anchor" href="#dns-based-load-balancing" aria-label="Permalink to &quot;DNS-based load balancing&quot;">​</a></h3><p>DNS can participate in load balancing by returning different IPs depending on geography, availability, or traffic distribution — e.g. a user in Malaysia gets a Singapore IP and connects directly to that region. DNS is often the <strong>first level of global traffic distribution</strong>. (Details in <code>networking/dns/DnsResolution.md</code>.)</p><h3 id="software-vs-hardware-load-balancers" tabindex="-1">Software vs hardware load balancers <a class="header-anchor" href="#software-vs-hardware-load-balancers" aria-label="Permalink to &quot;Software vs hardware load balancers&quot;">​</a></h3><p>For interviews, software load balancers matter far more: <strong>NGINX, HAProxy, AWS ALB</strong> — these are what backend engineers actually touch. Hardware load balancers exist; know <em>that</em> they exist, but spend prep time on software.</p><h3 id="nginx" tabindex="-1">NGINX <a class="header-anchor" href="#nginx" aria-label="Permalink to &quot;NGINX&quot;">​</a></h3><p>Commonly used as a Layer 7 load balancer — inspects paths/headers/cookies and routes accordingly (<code>/api/* → cluster A</code>, <code>/admin/* → cluster B</code>). NGINX can also operate at Layer 4, but its most-discussed use case is L7 routing.</p><h3 id="self-managed-vs-cloud-managed" tabindex="-1">Self-managed vs cloud-managed <a class="header-anchor" href="#self-managed-vs-cloud-managed" aria-label="Permalink to &quot;Self-managed vs cloud-managed&quot;">​</a></h3><ul><li><strong>Self-managed (NGINX you install):</strong> you own configuration, deployment, health checks, scaling.</li><li><strong>Cloud-managed (AWS ALB):</strong> you configure routing rules; the provider manages availability, scaling, health monitoring.</li></ul><p>Interviewers care that you understand the concept, not every cloud-specific setting.</p><h3 id="consistent-hashing-for-routing" tabindex="-1">Consistent hashing for routing <a class="header-anchor" href="#consistent-hashing-for-routing" aria-label="Permalink to &quot;Consistent hashing for routing&quot;">​</a></h3><p>Consistent hashing maps a request to a particular server based on a key (e.g. <code>hash(userId) → Server B</code>) — the same user keeps reaching the same destination.</p><p><strong>Modern use case:</strong> historically explained via sticky sessions (user&#39;s cart in Server B&#39;s memory). Modern systems avoid in-memory session affinity by storing state in Redis/databases/shared storage. The more realistic example today is <strong>distributed cache node selection</strong> — the same user&#39;s cached data consistently lands on the same Redis node instead of spreading across cache servers. (Mechanics in <code>system_design/caching/CachingAndDistributedCache.md</code>.)</p><h3 id="load-balancer-redundancy" tabindex="-1">Load balancer redundancy <a class="header-anchor" href="#load-balancer-redundancy" aria-label="Permalink to &quot;Load balancer redundancy&quot;">​</a></h3><p>The load balancer itself can become a single point of failure — if the only LB dies, the entire system is unavailable. Solution:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Users → DNS → [LB-A | LB-B] → servers</span></span></code></pre></div><p>Multiple load balancers + health checks + failover. <strong>The load balancer itself must be highly available.</strong></p><h3 id="dns-redundancy-—-the-natural-follow-up" tabindex="-1">DNS redundancy — the natural follow-up <a class="header-anchor" href="#dns-redundancy-—-the-natural-follow-up" aria-label="Permalink to &quot;DNS redundancy — the natural follow-up&quot;">​</a></h3><p>&quot;What if DNS fails?&quot; DNS providers are themselves distributed: records are served from many DNS servers globally, responses are cached, and multiple servers serve the same records. DNS is designed to avoid being a single point of failure.</p><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><strong>&quot;Layer 4 means regional routing.&quot;</strong> Not exactly — that&#39;s a useful intuition, but L4 is defined by the <em>information it uses</em> (IPs, ports, TCP/UDP metadata). Choosing a region is just one possible use of it.</li><li><strong>&quot;DNS load balancing and L4 load balancing are the same.&quot;</strong> Not quite — DNS-based routing happens <em>before</em> any load balancer is reached (User → DNS decision → regional endpoint → LB → servers). DNS participates in global distribution but is not itself an L4 load balancer.</li><li><strong>&quot;If DNS already sends users to the right region, why another load balancer?&quot;</strong> DNS only picks the regional entry point. Inside the region there may be 10–500 backend servers — a load balancer still distributes among them.</li><li><strong>&quot;Consistent hashing is mainly for sticky sessions.&quot;</strong> Historically yes; today the stronger example is distributed caches (Redis cluster). The session example is valid but less representative of modern architectures.</li><li><strong>&quot;Do we keep adding load balancers in front of load balancers forever?&quot;</strong> No — that would be infinite recursion. Redundancy comes from multiple LBs + health checks + failover under DNS, not an endless chain.</li><li><strong>&quot;Then who protects DNS?&quot;</strong> DNS infrastructure is already globally distributed and replicated — the answer is not a load balancer in front of DNS.</li></ol><h2 id="performance-characteristics" tabindex="-1">Performance characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance characteristics&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Layer 4</th><th>Layer 7</th></tr></thead><tbody><tr><td>Pros</td><td>Faster, less inspection work, lower overhead</td><td>Path/header/cookie-based routing</td></tr><tr><td>Cons</td><td>Cannot route on application data</td><td>Must inspect requests — more processing overhead</td></tr></tbody></table><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><h3 id="what-interviewers-usually-care-about-sde2" tabindex="-1">What interviewers usually care about (SDE2) <a class="header-anchor" href="#what-interviewers-usually-care-about-sde2" aria-label="Permalink to &quot;What interviewers usually care about (SDE2)&quot;">​</a></h3><p>Why load balancing exists · L4 vs L7 · DNS-based routing · NGINX as software LB · consistent hashing concept · LB redundancy. Product-specific configuration knowledge is not expected — mechanism and trade-offs beat vendor features.</p><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. What information does a Layer 4 load balancer use?</strong> A. IP addresses, ports, and transport-layer metadata.</p><p><strong>Q. What information does a Layer 7 load balancer use?</strong> A. URL paths, headers, cookies, hostnames — application-layer data.</p><p><strong>Q. Why can DNS be considered a form of load balancing?</strong> A. It can return different IPs based on geography, availability, or traffic distribution.</p><p><strong>Q. If DNS routes me to Singapore, why do I still need a load balancer there?</strong> A. DNS only chooses the regional entry point; the regional LB distributes traffic among the backend servers.</p><p><strong>Q. What is the core idea behind consistent hashing?</strong> A. The same key (e.g. user ID) consistently maps to the same backend node.</p><p><strong>Q. What is a realistic modern use case for consistent hashing?</strong> A. Routing data to the correct node in a distributed cache such as Redis.</p><p><strong>Q. How do we avoid the load balancer becoming a single point of failure?</strong> A. Deploy multiple load balancers with health checks and failover routing traffic to healthy ones.</p>`,49)])])}const p=e(o,[["render",i]]);export{g as __pageData,p as default};
